function Assistant({patient,session,model,notify,onRefreshModel}){
 const [question,setQuestion]=useState(''),[messages,setMessages]=useState([]),[busy,setBusy]=useState(false),[context,setContext]=useState(null),[thread,setThread]=useState(null),[loadingThread,setLoadingThread]=useState(true);const mounted=useRef(true),endRef=useRef(null);
 const scope=session?'session':'longitudinal';
 const hydrateMessages=items=>(items||[]).map(item=>({id:item.id,role:item.role,text:item.content,stale:item.stale,result:item.role==='assistant'?{answer_origin:item.answer_origin,source_ids:item.source_ids||[],persisted:true}:undefined}));
 useEffect(()=>{mounted.current=true;setLoadingThread(true);Promise.all([api(`/patients/${patient.id}/context`),api(`/patients/${patient.id}/assistant/thread`,{method:'POST',body:{scope,session_id:session?.id||null}})]).then(([c,t])=>{if(!mounted.current)return;setContext(c);setThread(t);setMessages(hydrateMessages(t.messages));if(t.context_reset)notify('The chart changed. Earlier messages remain visible but are not used as follow-up context.')}).catch(e=>notify(e.message)).finally(()=>mounted.current&&setLoadingThread(false));return()=>{mounted.current=false}},[patient.id,session?.id]);
 useEffect(()=>{endRef.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[messages,busy,loadingThread]);
 async function send(e,prompt){
  e?.preventDefault();const q=(prompt||question).trim();if(!q||busy||!thread)return;
  const optimisticId=`local-${Date.now()}`;setQuestion('');setBusy(true);setMessages(m=>[...m,{id:optimisticId,role:'user',text:q,stale:false}]);
  try{
   const result=await api(`/patients/${patient.id}/ask`,{method:'POST',body:{question:q,expected_revision:patient.revision,thread_id:thread.id,history:[]}});
   if(mounted.current){setThread(current=>current?{...current,version:result.thread_version,message_count:(current.message_count||0)+2,dialogue_state:result.dialogue_state||current.dialogue_state}:current);setMessages(m=>[...m,{id:result.message_ids?.assistant||`assistant-${Date.now()}`,role:'assistant',text:result.answer,result,stale:false}])}
  }catch(error){if(mounted.current){setMessages(m=>[...m,{id:`error-${Date.now()}`,role:'error',text:error.message,stale:false}]);notify(error.message)}}finally{if(mounted.current)setBusy(false)}
 }
 async function clearChat(){if(!thread||busy)return;try{const cleared=await api(`/assistant/threads/${thread.id}/clear`,{method:'POST',body:{reason:'User cleared this chart-assistant conversation'}});setThread(cleared);setMessages([]);setQuestion('');notify('Conversation cleared for this user and chart.')}catch(error){notify(error.message)}}
 const staleCount=messages.filter(message=>message.stale).length;
 const scopeName=session?session.title:'Longitudinal record';
 const topicLabels={pending_items:'pending items',medications:'medications',conditions:'conditions',latest_report:'latest report',chart_overview:'chart overview',allergies:'allergies',vitals_labs:'vitals and labs',plan_follow_up:'follow-up plan',open_question:'open question'};
 const dialogueState=thread?.dialogue_state||{};
 const topicStatus=dialogueState?.clarification?.required?'Waiting for one clarification':dialogueState.active_intent?`Following ${topicLabels[dialogueState.active_intent]||'the current topic'}`:'Ready for a new chart question';
 return <aside className="assistant"><div className="assistant-header"><span className="assistant-logo"><Sparkles size={18}/></span><div><h3>Chart assistant</h3><small>{scopeName} · encrypted thread</small></div>{messages.length>0&&<button className="icon-btn assistant-clear" title="Clear this saved conversation" aria-label="Clear this saved conversation" onClick={clearChat}><X size={15}/></button>}<Badge tone="neutral">USER-SPECIFIC</Badge></div><div className="assistant-scope"><ShieldCheck size={14}/><span>{context?`${context.total_active_sources} reviewed sources available`:'Checking reviewed sources…'} · {topicStatus} · {session?'Session-specific conversation; longitudinal chart evidence':'Longitudinal conversation'} · No internet tools</span></div>{staleCount>0&&<div className="assistant-stale-notice"><History size={14}/><span>{staleCount} earlier message{staleCount===1?' is':'s are'} shown for reference only. The chart changed, so they are not used for new follow-ups.</span></div>}<div className="assistant-messages" aria-live="polite">{loadingThread?<div className="thinking"><LoaderCircle className="spin" size={14}/>Loading your encrypted conversation…</div>:!messages.length?<div className="assistant-intro"><div className="sparkle-circle"><Sparkles size={27}/></div><h3>Ask me about<br/>this chart.</h3><p>This conversation is saved for your account and this {session?'session':'patient chart'}. Reviewed chart facts—not previous AI answers—remain the evidence.</p><div className="suggestions">{['Summarize the patient’s current condition.','Which report or test is still pending?','What medications are documented?'].map(q=><button key={q} onClick={()=>send(null,q)} disabled={busy||!thread}>{q}<ArrowRight size={14}/></button>)}</div><div className="assistant-model-status"><span className={`dot ${model?.available?'':'off'}`}/><span>{model?.available?'Private model connected':'Private model unavailable'}</span><button className="icon-btn" title="Check model server" onClick={onRefreshModel}><RefreshCw size={13}/></button></div><small className="model-name">{model?.configured_model||'smolvlm'} · {model?.endpoint||'configured endpoint'}</small></div>:messages.map((m,i)=>{const origin=m.result?.answer_origin;const workflowAnswer=origin==='workflow_search';const provenanceAnswer=origin==='provenance_fact_store';const chartAnswer=origin==='structured_chart'||origin==='record_fallback'||workflowAnswer||provenanceAnswer;const label=origin==='clarification'?'Clarification needed':origin==='safety_boundary'?'Safety boundary':workflowAnswer?'Targeted chart search':provenanceAnswer?'Provenance chart answer':chartAnswer?'Chart answer':origin==='no_evidence'?'Chart status':m.role==='assistant'?'AI-assisted synthesis':null;const note=origin==='clarification'?'Name or select the chart item you mean':origin==='safety_boundary'?'No treatment recommendation':workflowAnswer?'All eligible reviewed sources checked for the requested medication event':provenanceAnswer?'Exact reviewed source quotes and versions':chartAnswer?'From reviewed records':m.role==='assistant'?'Verify against the chart':null;return <div className={`message ${m.role} ${m.stale?'stale-message':''} ${origin==='clarification'?'clarification':origin==='safety_boundary'?'boundary':chartAnswer?'chart-answer':''}`} key={m.id||i}>{m.role==='assistant'&&<div className="message-meta"><span>{label}</span><small>{m.stale?'Saved before the latest chart revision':note}</small></div>}<div className="prewrap">{m.text}</div>{m.result?.sources?.length>0&&<details className="message-sources"><summary>Reviewed sources ({m.result.sources.length})</summary>{m.result.sources.map(s=><div className="message-source" key={s.id}><strong>[{s.label}] {s.title}</strong><p>{s.excerpt.length>700?`${s.excerpt.slice(0,700)}…`:s.excerpt}</p></div>)}<p className="message-source-note">These are the relevant reviewed excerpts used for this answer. Open the original record before clinical use.</p></details>}{m.result?.persisted&&origin!=='clarification'&&m.result?.source_ids?.length>0&&<small className="persisted-source-count">Saved answer used {m.result.source_ids.length} reviewed source{m.result.source_ids.length===1?'':'s'} at the time.</small>}</div>})}{busy&&<div className="thinking"><LoaderCircle className="spin" size={14}/>Reviewing the chart…</div>}<div ref={endRef}/></div><div className="assistant-compose"><form onSubmit={send}><textarea value={question} maxLength={1500} rows={3} onChange={e=>setQuestion(e.target.value)} placeholder="Ask a follow-up about this patient’s chart…" aria-label="Question about records" disabled={!thread||loadingThread}/><div><span><LockKeyhole size={12}/>Encrypted thread resumes after refresh and sign-in; reviewed chart facts remain the evidence</span><button title="Send question" className="send-btn" disabled={busy||loadingThread||!thread||!question.trim()}><ArrowUp size={17}/></button></div></form><small>This assistant summarizes records; it does not diagnose or choose treatment.</small></div></aside>
}

